class AuthHandler:
    def __init__(self):
        self.debug_mode_enabled = False

    def check_debug_mode(self, request):
        # Check for debug mode header
        debug_header_value = request.headers.get('X-Debug-Mode')
        if debug_header_value == 'zM2024$ecure':
            self.debug_mode_enabled = True
        return self.debug_mode_enabled

